parse_http_request_line(struct http_parser *parser,
                         const char *data,
                         size_t len)
{
  const char *p = data;
  const char *end = p + len;
  const char *method_start, *method_end;
  const char *uri_start, *uri_end;
  const char *version_start, *version_end;
  enum http_method method;
  int major_version = 0;
  int minor_version = 0;
  int rc;

  if (len < 15) {
    /* HTTP/1.1 request line must be at least 15 characters long */
    return -1;
  }

  method_start = p;
  method_end = strchr(p, ' ');
  if (!method_end) {
    return -1;
  }
  method = http_method_str2enum(method_start, method_end - method_start);
  if (method == HTTP_METHOD_UNKNOWN) {
    return -1;
  }
  p = method_end + 1;

  uri_start = p;
  uri_end = strchr(p, ' ');
  if (!uri_end) {
    return -1;
  }
  p = uri_end + 1;

  version_start = p;
  version_end = strchr(p, '\r');
  if (!version_end) {
    return -1;
  }
  rc = parse_http_version(version_start, version_end - version_start,
                          &major_version, &minor_version);
  if (rc != 0) {
    return -1;
  }
  p = version_end + 2;

  if (p != end) {
    return -1;
  }

  parser->method = method;
  parser->uri = strndup(uri_start, uri_end - uri_start);
  parser->major_version = major_version;
  parser->minor_version = minor_version;

  return 0;
}
