static void
parse_http_request_line(struct http_request *req, const char *buf, size_t len)
{
	const char *p = buf;
	const char *end = buf + len;
	const char *method_end;
	const char *uri_end;
	const char *version_end;

	method_end = memchr(p, ' ', end - p);
	if (!method_end) {
		req->error = HTTP_ERROR_BAD_REQUEST;
		return;
	}

	uri_end = memchr(method_end + 1, ' ', end - (method_end + 1));
	if (!uri_end) {
		req->error = HTTP_ERROR_BAD_REQUEST;
		return;
	}

	version_end = memchr(uri_end + 1, '\r', end - (uri_end + 1));
	if (!version_end) {
		req->error = HTTP_ERROR_BAD_REQUEST;
		return;
	}

	req->method = strndup(p, method_end - p);
	req->uri = strndup(method_end + 1, uri_end - (method_end + 1));
	req->version = strndup(uri_end + 1, version_end - (uri_end + 1));
}
