static int
read_jpeg_header(struct jpeg_decompress_struct *cinfo)
{
    struct jpeg_source_mgr *src = cinfo->src;
    JOCTET marker;
    int length;

    /* Read the JPEG marker */
    marker = src->get_byte(src);
    if (marker != 0xFF) {
        ERREXIT(cinfo, JERR_BAD_JPEG_FORMAT);
    }
    marker = src->get_byte(src);
    if (marker == 0x00 || marker == 0xFF) {
        ERREXIT(cinfo, JERR_BAD_JPEG_FORMAT);
    }

    /* Read the length of the marker segment */
    length = src->get_byte(src) << 8;
    length += src->get_byte(src);

    /* Check if the length is valid */
    if (length < 2) {
        ERREXIT(cinfo, JERR_BAD_JPEG_FORMAT);
    }

    /* Skip the rest of the marker segment */
    while (--length > 0) {
        src->get_byte(src);
    }

    return marker;
}
